                out.append({'color':int(c),'cells':comp,'pat':pat,'bbox':(rs,cs)})
    return g,bg,out
def solve(g):
    ga=np.array(g); H,W=ga.shape
    _,bg,out=comps_of(ga)
    colcnt=Counter(c['color'] for c in out)
    uniq=[c for c in out if colcnt[c['color']]==1]
    tgt=max(uniq,key=lambda c:len(c['cells']))['color']
    gr=defaultdict(list)
    for c in out: gr[c['pat']].append(c)
    res=ga.copy()
    for vs in gr.values():
        if len(vs)<2: continue
        # non-border members
        inner=[c for c in vs if not any(r==0 or r==H-1 or cc==0 or cc==W-1 for r,cc in c['cells'])]
        cands=inner if len(inner)>=1 else vs
        chg=min(cands,key=lambda c:c['color'])  # smallest color among chosen set
        for (r,cc) in chg['cells']:
            res[r,cc]=tgt
    return res.tolist()
for k in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4']:
    print(k, solve(G[k+' input'])==G[k+' output'])
print(json.dumps(solve(G['Test input'])))
